import{_ as e,o as a,c as d,ag as r}from"./chunks/framework.DMXcdKmJ.js";const p=JSON.parse('{"title":"安装前准备","description":"准备好 Ubuntu 24 服务器、完整安装包、访问地址和管理员信息，再开始安装。","frontmatter":{"title":"安装前准备","description":"准备好 Ubuntu 24 服务器、完整安装包、访问地址和管理员信息，再开始安装。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/installation/prepare.md","filePath":"zh/安装运维/安装前准备.md"}'),o={name:"zh/installation/prepare.md"};function i(l,t,n,s,h,c){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="安装前准备" tabindex="-1">安装前准备 <a class="header-anchor" href="#安装前准备" aria-label="Permalink to &quot;安装前准备&quot;">​</a></h1><p>不清楚服务器架构、内存、磁盘、终端或 sudo 是什么，可先查<a href="/induframe-docs/zh/reference/glossary.html">常用术语解释</a>，再按本页核对准备条件。</p><p>开始前先确认四件事：<strong>装在哪台服务器、安装包放在哪里、装好后从哪里打开、管理员密码由谁保管。</strong></p><p>如果你只负责日常使用，可让服务器维护人员完成安装，向组织管理员索取公共入口和自己的账号。</p><h2 id="_1-优先准备-ubuntu-24-服务器" tabindex="-1">1. 优先准备 Ubuntu 24 服务器 <a class="header-anchor" href="#_1-优先准备-ubuntu-24-服务器" aria-label="Permalink to &quot;1. 优先准备 Ubuntu 24 服务器&quot;">​</a></h2><p><strong>目前只测试了 Ubuntu 24，优先推荐使用这个系统。其他系统尚未测试，不作为已验证环境推荐。</strong></p><p>请与服务器维护人员一起检查：</p><table tabindex="0"><thead><tr><th>要检查什么</th><th>怎样才可以继续</th></tr></thead><tbody><tr><td>操作系统</td><td>使用目前已测试的 Ubuntu 24</td></tr><tr><td>安装包</td><td>与服务器架构匹配；不确定该选哪种时，请交付人员确认</td></tr><tr><td>系统权限</td><td>服务器账号可以使用 <code>sudo</code>，且你知道该账号的系统密码</td></tr><tr><td>服务器用途</td><td>明确用于本次安装；已有其他服务时，先确认不会影响它们</td></tr><tr><td>系统盘</td><td>同时保留至少 30 GiB 且至少 20% 可用空间</td></tr><tr><td>独立数据盘</td><td>如果另外使用数据盘，该盘也要同时满足上述余量</td></tr><tr><td>网络</td><td>你使用的电脑能访问计划中的服务器地址</td></tr></tbody></table><p>30 GiB 是必须保留的余量，不是整台服务器只需这么大。业务数据、工程文件和后续增长还需额外空间。详细范围见<a href="/induframe-docs/zh/reference/system-requirements.html">系统与安装要求</a>。</p><h2 id="_2-取得完整安装包并解压" tabindex="-1">2. 取得完整安装包并解压 <a class="header-anchor" href="#_2-取得完整安装包并解压" aria-label="Permalink to &quot;2. 取得完整安装包并解压&quot;">​</a></h2><p>向交付人员取得适用的 <strong>InduFrame v1.0 完整安装包</strong>，上传到服务器并完整解压。不要拆开移动包内文件，也不要只下载一个脚本。</p><p>进入解压后的文件夹，应能看到 <code>install.sh</code>、<code>uninstall.sh</code> 和说明文件。后续命令就在这个文件夹运行。记下它的位置，安装结束后也保留完整原包。</p><p>离线安装包仍可能需要服务器已有必要的系统网络组件。完全不能联网的服务器，请先由维护人员备好这些组件。</p><h2 id="_3-准备安装位置和访问地址" tabindex="-1">3. 准备安装位置和访问地址 <a class="header-anchor" href="#_3-准备安装位置和访问地址" aria-label="Permalink to &quot;3. 准备安装位置和访问地址&quot;">​</a></h2><table tabindex="0"><thead><tr><th>向导会问什么</th><th>你要准备什么</th></tr></thead><tbody><tr><td>程序存放位置</td><td>没有特殊要求时用默认 <code>/opt</code>，程序实际放在 <code>/opt/induframe</code></td></tr><tr><td>公共访问地址或域名</td><td>组织成员能够访问的服务器 IP 地址或域名</td></tr><tr><td>公共访问端口</td><td>默认 <code>443</code>，由维护人员确认未被占用</td></tr><tr><td>管理入口端口</td><td>默认 <code>18100</code>，与公共端口不同</td></tr></tbody></table><p>公共入口供组织成员日常使用；管理入口供平台超级管理员管理组织。安装结束后会分别打印完整地址，后续直接复制使用。</p><p>管理入口通常需要从内网或管理网络访问，先确认平台管理员的电脑能够连接该网络。</p><p>服务器启用防火墙或云安全组时，先按<a href="/induframe-docs/zh/installation/network.html">配置网络与防火墙</a>区分中心管理入口、环境入口和可选独立入口。只开放实际需要的端口，不要一次性全部放行。</p><div class="tip custom-block"><p class="custom-block-title">安装包文件夹和程序目录不同</p><p>安装包文件夹放着解压出的文件，程序目录由安装器创建。向导填写默认 <code>/opt</code> 时，不要再自己追加 <code>induframe</code>，也不要把程序装进安装包文件夹。</p></div><h2 id="_4-准备密码和证书方式" tabindex="-1">4. 准备密码和证书方式 <a class="header-anchor" href="#_4-准备密码和证书方式" aria-label="Permalink to &quot;4. 准备密码和证书方式&quot;">​</a></h2><ul><li><strong>服务器账号密码</strong>：向导取得系统管理权限时使用。</li><li><strong>平台超级管理员密码</strong>：安装过程中由你设置，用于管理入口。默认用户名 <code>admin</code>，建议密码使用 8–72 个英文字母、数字或半角符号。</li><li><strong>组织管理员密码</strong>：安装后在网页中单独设置，见<a href="/induframe-docs/zh/installation/first-setup.html">完成首次设置</a>。不要把这三种密码混为一谈。</li></ul><p>没有专门安排时，证书方式选默认 <code>self-signed</code>，由安装器生成；浏览器可能出现信任提醒，需要维护人员核对后处理。</p><p>只有维护人员已准备好证书、私钥等文件时，才选择 <code>provided</code>。向导中填写文件路径，不粘贴文件内容。完整字段限制见<a href="/induframe-docs/zh/reference/install-options.html">安装参数</a>。</p><h2 id="准备好了吗" tabindex="-1">准备好了吗 <a class="header-anchor" href="#准备好了吗" aria-label="Permalink to &quot;准备好了吗&quot;">​</a></h2><ul><li>[ ] 已确认服务器为 Ubuntu 24，账号有安装权限。</li><li>[ ] 磁盘余量满足要求，完整安装包已上传并解压。</li><li>[ ] 程序位置、公共地址和端口已确认。</li><li>[ ] 防火墙、安全组及远程管理通道已确认，内部网段没有冲突。</li><li>[ ] 两个入口由谁使用、密码由谁保管已经说清。</li><li>[ ] 已确定使用默认证书，或已备好证书文件。</li></ul><p>条件满足后，继续<a href="/induframe-docs/zh/installation/install.html">安装中心</a>。不清楚服务器用途、已有数据或网络设置时，先确认再安装。</p>',26)])])}const m=e(o,[["render",i]]);export{p as __pageData,m as default};
